import { useEffect, useMemo, useState } from "react";
import axios from "axios";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis
} from "recharts";
import cameroonDistricts, { regionOptions } from "../data/cameroonDistricts";
import "../styles/AdminPage.css";

const initialFormState = {
  date: "",
  region: "",
  district: "",
  suspected: "",
  confirmed: "",
  deaths: ""
};

function AdminPage() {
  const [formData, setFormData] = useState(initialFormState);
  const [loading, setLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [reports, setReports] = useState([]);
  const [geoJson, setGeoJson] = useState(null);
  const [dashboardLoading, setDashboardLoading] = useState(true);
  const [dashboardError, setDashboardError] = useState("");
  const [hoveredRegion, setHoveredRegion] = useState(null);

  useEffect(() => {
    const fetchDashboardData = async () => {
      setDashboardLoading(true);
      setDashboardError("");

      try {
        const [reportsResponse, geoResponse] = await Promise.all([
          axios.get("http://localhost:5000/api/reports"),
          axios.get("http://localhost:5000/api/regions-geojson")
        ]);

        setReports(Array.isArray(reportsResponse.data) ? reportsResponse.data : []);
        setGeoJson(geoResponse.data);
      } catch (error) {
        setDashboardError(
          error.response?.data?.message ||
            "Unable to load dashboard data. Check that backend is running."
        );
      } finally {
        setDashboardLoading(false);
      }
    };

    fetchDashboardData();
  }, []);

  const districtOptions = useMemo(
    () => (formData.region ? cameroonDistricts[formData.region] || [] : []),
    [formData.region]
  );

  const cfr = useMemo(() => {
    const confirmed = Number(formData.confirmed) || 0;
    const deaths = Number(formData.deaths) || 0;

    if (confirmed === 0) {
      return 0;
    }

    return Number(((deaths / confirmed) * 100).toFixed(2));
  }, [formData.confirmed, formData.deaths]);

  const normalizeRegionName = (name) => {
    const cleaned = String(name || "")
      .toLowerCase()
      .replace(/[^a-z]/g, "");

    const aliases = {
      adamaoua: "adamawa",
      northwest: "northwest",
      southwest: "southwest",
      farnorth: "farnorth"
    };

    return aliases[cleaned] || cleaned;
  };

  const regionalData = useMemo(() => {
    const totals = new Map(
      regionOptions.map((region) => [
        normalizeRegionName(region),
        {
          region,
          suspected: 0,
          confirmed: 0,
          deaths: 0,
          cfr: 0
        }
      ])
    );

    for (const report of reports) {
      const key = normalizeRegionName(report.region);

      if (!totals.has(key)) {
        totals.set(key, {
          region: report.region,
          suspected: 0,
          confirmed: 0,
          deaths: 0,
          cfr: 0
        });
      }

      const bucket = totals.get(key);
      bucket.suspected += Number(report.suspected) || 0;
      bucket.confirmed += Number(report.confirmed) || 0;
      bucket.deaths += Number(report.deaths) || 0;
      bucket.cfr =
        bucket.confirmed === 0
          ? 0
          : Number(((bucket.deaths / bucket.confirmed) * 100).toFixed(2));
    }

    return Array.from(totals.values()).sort((a, b) => b.confirmed - a.confirmed);
  }, [reports]);

  const mapFeatures = useMemo(() => {
    if (!geoJson?.features) {
      return [];
    }

    const byRegion = new Map(
      regionalData.map((item) => [normalizeRegionName(item.region), item])
    );

    return geoJson.features.map((feature) => {
      const name = feature?.properties?.shapeName || "Unknown";
      const regionStats = byRegion.get(normalizeRegionName(name)) || {
        region: name,
        suspected: 0,
        confirmed: 0,
        deaths: 0,
        cfr: 0
      };

      return {
        ...feature,
        regionStats
      };
    });
  }, [geoJson, regionalData]);

  const maxConfirmed = useMemo(
    () => Math.max(0, ...regionalData.map((item) => item.confirmed)),
    [regionalData]
  );

  const getFeatureBbox = (geometry) => {
    const points = [];
    const coordinates = geometry?.coordinates || [];

    if (geometry?.type === "Polygon") {
      coordinates.forEach((ring) => ring.forEach((pt) => points.push(pt)));
    }

    if (geometry?.type === "MultiPolygon") {
      coordinates.forEach((polygon) => {
        polygon.forEach((ring) => ring.forEach((pt) => points.push(pt)));
      });
    }

    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    points.forEach(([x, y]) => {
      minX = Math.min(minX, x);
      minY = Math.min(minY, y);
      maxX = Math.max(maxX, x);
      maxY = Math.max(maxY, y);
    });

    return {
      minX,
      minY,
      maxX,
      maxY,
      width: maxX - minX,
      height: maxY - minY
    };
  };

  const mapBbox = useMemo(() => {
    const boxes = mapFeatures
      .map((feature) => getFeatureBbox(feature.geometry))
      .filter((box) => Number.isFinite(box.minX));

    if (!boxes.length) {
      return null;
    }

    return {
      minX: Math.min(...boxes.map((b) => b.minX)),
      minY: Math.min(...boxes.map((b) => b.minY)),
      maxX: Math.max(...boxes.map((b) => b.maxX)),
      maxY: Math.max(...boxes.map((b) => b.maxY))
    };
  }, [mapFeatures]);

  const mapWidth = 760;
  const mapHeight = 500;
  const mapPadding = 20;

  const projectPoint = (lon, lat) => {
    if (!mapBbox) {
      return [0, 0];
    }

    const lonSpan = Math.max(mapBbox.maxX - mapBbox.minX, 0.0001);
    const latSpan = Math.max(mapBbox.maxY - mapBbox.minY, 0.0001);

    const x =
      mapPadding + ((lon - mapBbox.minX) / lonSpan) * (mapWidth - mapPadding * 2);
    const y =
      mapHeight -
      mapPadding -
      ((lat - mapBbox.minY) / latSpan) * (mapHeight - mapPadding * 2);

    return [x, y];
  };

  const toSvgPath = (geometry) => {
    if (!geometry?.coordinates) {
      return "";
    }

    const drawRing = (ring) =>
      ring
        .map(([lon, lat], index) => {
          const [x, y] = projectPoint(lon, lat);
          return `${index === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`;
        })
        .join(" ") + " Z";

    if (geometry.type === "Polygon") {
      return geometry.coordinates.map((ring) => drawRing(ring)).join(" ");
    }

    if (geometry.type === "MultiPolygon") {
      return geometry.coordinates
        .map((polygon) => polygon.map((ring) => drawRing(ring)).join(" "))
        .join(" ");
    }

    return "";
  };

  const getHotspotColor = (confirmed) => {
    if (maxConfirmed === 0) {
      return "#edf4ff";
    }

    const ratio = confirmed / maxConfirmed;

    if (ratio > 0.8) {
      return "#a50f15";
    }
    if (ratio > 0.6) {
      return "#de2d26";
    }
    if (ratio > 0.4) {
      return "#fb6a4a";
    }
    if (ratio > 0.2) {
      return "#fc9272";
    }
    return "#fee5d9";
  };

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((prev) => {
      if (name === "region") {
        return { ...prev, region: value, district: "" };
      }

      return { ...prev, [name]: value };
    });

    setSuccessMessage("");
    setErrorMessage("");
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setSuccessMessage("");
    setErrorMessage("");

    const payload = {
      date: formData.date,
      region: formData.region,
      district: formData.district,
      suspected: Number(formData.suspected) || 0,
      confirmed: Number(formData.confirmed) || 0,
      deaths: Number(formData.deaths) || 0,
      cfr
    };

    try {
      const response = await axios.post("http://localhost:5000/api/reports", payload);
      setSuccessMessage("Report submitted successfully.");
      setFormData(initialFormState);

      if (response?.data?.data) {
        setReports((prev) => [response.data.data, ...prev]);
      }
    } catch (error) {
      setErrorMessage(
        error.response?.data?.message ||
          "Submission failed. Please verify the server and try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="admin-page">
      <section className="admin-card" aria-labelledby="admin-page-title">
        <h1 id="admin-page-title">Cholera Case Data Entry - Cameroon</h1>
        <p className="admin-subtitle">
          Use this form to submit daily district-level cholera surveillance reports.
        </p>

        <form className="admin-form" onSubmit={handleSubmit}>
          <label htmlFor="date">Report Date</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />

          <label htmlFor="region">Region</label>
          <select
            id="region"
            name="region"
            value={formData.region}
            onChange={handleChange}
            required
          >
            <option value="">Select a region</option>
            {regionOptions.map((region) => (
              <option key={region} value={region}>
                {region}
              </option>
            ))}
          </select>

          <label htmlFor="district">District</label>
          <select
            id="district"
            name="district"
            value={formData.district}
            onChange={handleChange}
            required
            disabled={!formData.region}
          >
            <option value="">Select a district</option>
            {districtOptions.map((district) => (
              <option key={district} value={district}>
                {district}
              </option>
            ))}
          </select>

          <label htmlFor="suspected">Suspected Cases</label>
          <input
            id="suspected"
            name="suspected"
            type="number"
            min="0"
            value={formData.suspected}
            onChange={handleChange}
            required
          />

          <label htmlFor="confirmed">Confirmed Cases</label>
          <input
            id="confirmed"
            name="confirmed"
            type="number"
            min="0"
            value={formData.confirmed}
            onChange={handleChange}
            required
          />

          <label htmlFor="deaths">Deaths</label>
          <input
            id="deaths"
            name="deaths"
            type="number"
            min="0"
            value={formData.deaths}
            onChange={handleChange}
            required
          />

          <label htmlFor="cfr">CFR (%)</label>
          <input id="cfr" name="cfr" type="text" value={cfr} readOnly />

          <button type="submit" disabled={loading}>
            {loading ? "Submitting..." : "Submit Report"}
          </button>
        </form>

        {successMessage && (
          <p className="status-message success" role="status">
            {successMessage}
          </p>
        )}

        {errorMessage && (
          <p className="status-message error" role="alert">
            {errorMessage}
          </p>
        )}
      </section>

      <section className="dashboard-card" aria-labelledby="regional-dashboard-title">
        <div className="dashboard-header">
          <h2 id="regional-dashboard-title">Regional Cholera Dashboard</h2>
          <p>Hotspots and regional trends from submitted surveillance reports.</p>
        </div>

        {dashboardLoading && <p className="dashboard-state">Loading dashboard...</p>}
        {dashboardError && <p className="dashboard-state error">{dashboardError}</p>}

        {!dashboardLoading && !dashboardError && (
          <div className="dashboard-grid">
            <article className="chart-card" aria-label="Confirmed and suspected cases by region">
              <h3>Regional Case Totals</h3>
              <div className="chart-wrap">
                <ResponsiveContainer width="100%" height={290}>
                  <BarChart data={regionalData} margin={{ top: 8, right: 12, left: 0, bottom: 42 }}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="region" angle={-32} textAnchor="end" interval={0} height={70} />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="suspected" name="Suspected" fill="#4aa3ff" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="confirmed" name="Confirmed" fill="#0d6cc5" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </article>

            <article className="chart-card" aria-label="Deaths and CFR by region">
              <h3>Fatality Pressure by Region</h3>
              <div className="chart-wrap">
                <ResponsiveContainer width="100%" height={290}>
                  <BarChart data={regionalData} margin={{ top: 8, right: 12, left: 0, bottom: 42 }}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="region" angle={-32} textAnchor="end" interval={0} height={70} />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="deaths" name="Deaths" fill="#cb2f2a" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="cfr" name="CFR (%)" fill="#f39c12" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </article>

            <article className="chart-card map-card" aria-label="Regional hotspot map">
              <h3>Regional Hotspot Map (Confirmed Cases)</h3>
              <div className="map-wrap">
                {mapFeatures.length > 0 ? (
                  <svg
                    className="hotspot-map"
                    viewBox={`0 0 ${mapWidth} ${mapHeight}`}
                    role="img"
                    aria-label="Cameroon regional hotspot map"
                  >
                    {mapFeatures.map((feature) => {
                      const regionName = feature?.properties?.shapeName || "Unknown";
                      const confirmed = feature.regionStats.confirmed;

                      return (
                        <path
                          key={feature?.properties?.shapeID || regionName}
                          d={toSvgPath(feature.geometry)}
                          fill={getHotspotColor(confirmed)}
                          stroke="#ffffff"
                          strokeWidth="1"
                          onMouseEnter={() => setHoveredRegion({ name: regionName, ...feature.regionStats })}
                          onMouseLeave={() => setHoveredRegion(null)}
                        />
                      );
                    })}
                  </svg>
                ) : (
                  <p className="dashboard-state">Map data unavailable.</p>
                )}

                <div className="map-legend" aria-hidden="true">
                  <span>Lower</span>
                  <div className="legend-scale" />
                  <span>Higher</span>
                </div>

                {hoveredRegion && (
                  <div className="map-tooltip">
                    <strong>{hoveredRegion.name}</strong>
                    <span>Confirmed: {hoveredRegion.confirmed}</span>
                    <span>Suspected: {hoveredRegion.suspected}</span>
                    <span>Deaths: {hoveredRegion.deaths}</span>
                    <span>CFR: {hoveredRegion.cfr}%</span>
                  </div>
                )}
              </div>
            </article>
          </div>
        )}
      </section>
    </main>
  );
}

export default AdminPage;
